def liiga_player_stats(
    season_from: int,
    season_to: int,
    tournament: str,
    data_type: Optional[str] = "basicStats",
    *,
    return_parsed: bool = True,
    return_as_pandas: bool = False,
    **kwargs,
) -> Union[pl.DataFrame, pd.DataFrame, Dict]:
    """Player stat table summed over a season range, by data_type (the whole league, unfiltered).

    Endpoint: ``GET https://liiga.fi/api/v2/players/stats/summed/{season_from}/{season_to}/{tournament}/true``
    Example URL: https://liiga.fi/api/v2/players/stats/summed/2026/2026/runkosarja/true?dataType=basicStats

    Args:
        season_from: First season (END year) of the range, e.g. 2026.
        season_to: Last season (END year) of the range, e.g. 2026.
        tournament: Tournament: runkosarja (regular season), playoffs, playout, qualifications, valmistavat_ottelut (preseason) or chl (Champions Hockey League).
        data_type: Stat table: basicStats, basicStatsGk, advancedStats, goalStats, shotStats, skatingStats, faceOffStats, penaltyStats, powerplayPenaltykillStats, passes, winningShotComp, winningShotCompGk, gameTime.
        return_parsed: parse the payload through parse_liiga -> polars DataFrame (default True). Pass return_parsed=False for the raw JSON Dict.
        return_as_pandas: with return_parsed, return a pandas DataFrame instead of polars.
        **kwargs: Forwarded to the underlying HTTP getter.

    Returns:
        A polars/pandas DataFrame by default; the raw JSON ``Dict`` when ``return_parsed=False``.

    Raises:
        sportsdataverse.errors.NoDataError: Liiga has nothing for the request (an unknown game, a tournament not played that season, a shot map before 2016).
        ValueError: The host answered 400 / 422 -- the request is wrong; retrying cannot help.
        AssetFetchError: The fetch failed (a non-2xx answer or a connection failure after retries, e.g. 401/403/429/5xx, or an empty or unreadable 200 body) -- the answer is unknown, not empty.

    Example:
        Quick start::

            from sportsdataverse.hockey.liiga import liiga_player_stats
            liiga_player_stats(season_from=2026, season_to=2026, tournament='runkosarja')

        See Also:
            * `Liiga`_ - the site whose API v2 these wrappers read
            * `fastRhockey`_ - SportsDataverse hockey package (R)

        .. _Liiga: https://liiga.fi/
        .. _fastRhockey: https://fastRhockey.sportsdataverse.org
    """
    if tournament not in ("runkosarja", "playoffs", "playout", "qualifications", "valmistavat_ottelut", "chl"):
        raise ValueError(
            f"tournament must be one of ('runkosarja', 'playoffs', 'playout', 'qualifications', 'valmistavat_ottelut', 'chl'); got {tournament!r}"
        )
    if data_type not in (
        "basicStats",
        "basicStatsGk",
        "advancedStats",
        "goalStats",
        "shotStats",
        "skatingStats",
        "faceOffStats",
        "penaltyStats",
        "powerplayPenaltykillStats",
        "passes",
        "winningShotComp",
        "winningShotCompGk",
        "gameTime",
    ):
        raise ValueError(
            f"data_type must be one of ('basicStats', 'basicStatsGk', 'advancedStats', 'goalStats', 'shotStats', 'skatingStats', 'faceOffStats', 'penaltyStats', 'powerplayPenaltykillStats', 'passes', 'winningShotComp', 'winningShotCompGk', 'gameTime'); got {data_type!r}"
        )
    _caller_params = kwargs.pop("params", None) or {}
    _params = {
        "dataType": data_type,
    }
    _params.update(_caller_params)
    raw = _get(
        f"https://liiga.fi/api/v2/players/stats/summed/{season_from}/{season_to}/{tournament}/true",
        params=_params,
        **kwargs,
    )
    if return_parsed:
        return parse_liiga(raw, return_as_pandas=return_as_pandas, columns=_PARSER_COLUMNS["player_stats"])
    return raw
